const posterCopies=[
  {badge:'秋日限定',title:'桂香入秋，<br>暖一杯剛好。',subtitle:'桂花清香 × 烏龍回甘',price:'新品上市・NT$ 65'},
  {badge:'本週主打',title:'一口桂香，<br>剛好的秋天。',subtitle:'冷熱皆宜・五店限定',price:'會員嚐鮮・NT$ 60'},
  {badge:'季節新品',title:'午後轉涼，<br>讓茶香暖場。',subtitle:'真茶萃取・清爽不膩',price:'桂花烏龍・NT$ 65'}
];
let posterCopyIndex=0;
function applyPosterCopy(){const copy=posterCopies[posterCopyIndex];document.querySelector('#posterBadge').textContent=copy.badge;document.querySelector('#posterTitle').innerHTML=copy.title;document.querySelector('#posterSubtitle').textContent=copy.subtitle;document.querySelector('.poster-copy strong').textContent=copy.price;document.querySelector('#posterHeadline').value=copy.title.replace('<br>','')}
document.querySelector('#regenerateCopy')?.addEventListener('click',()=>{posterCopyIndex=(posterCopyIndex+1)%posterCopies.length;applyPosterCopy();window.toast?.('報表內容 Agent 已換一版文案')});
document.querySelector('#generatePoster')?.addEventListener('click',()=>{const studio=document.querySelector('.marketing-studio');const button=document.querySelector('#generatePoster');studio.classList.add('is-generating');button.disabled=true;button.textContent='本地模型生成中…';document.querySelector('#posterApprovalState').textContent='生成中';setTimeout(()=>{posterCopyIndex=(posterCopyIndex+1)%posterCopies.length;applyPosterCopy();studio.classList.remove('is-generating');button.disabled=false;button.textContent='✦ 產生新版海報';document.querySelector('#posterApprovalState').textContent='待核准';window.toast?.('新版海報已在 RTX Spark Demo 完成')},1200)});
document.querySelector('#posterProduct')?.addEventListener('change',event=>{const prompts={'桂花烏龍':'秋日暖色調、桂花烏龍商品攝影、乾淨留白、在地茶飲品牌質感、無人物、無品牌文字。','黑糖薑奶':'溫暖木質調、熱飲蒸氣、黑糖與老薑元素、冬季療癒氛圍、無人物、無品牌文字。','燕麥焙茶拿鐵':'奶油米色、焙茶粉與燕麥元素、柔和日光、自然健康質感、無人物、無品牌文字。'};document.querySelector('#posterPrompt').textContent=prompts[event.target.value]});
document.querySelector('#approvePoster')?.addEventListener('click',()=>{document.querySelector('#posterApprovalState').textContent='已核准';document.querySelector('#posterApprovalState').className='done';window.toast?.('海報已送交並完成 Demo 核准')});
document.querySelector('#downloadPoster')?.addEventListener('click',()=>{const image=document.querySelector('#posterCanvas img');const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const context=canvas.getContext('2d');context.drawImage(image,0,0,1080,1350);const gradient=context.createLinearGradient(0,0,0,1350);gradient.addColorStop(0,'rgba(12,25,17,.32)');gradient.addColorStop(.5,'rgba(0,0,0,0)');gradient.addColorStop(1,'rgba(10,20,13,.72)');context.fillStyle=gradient;context.fillRect(0,0,1080,1350);const copy=posterCopies[posterCopyIndex];context.fillStyle='#fff';context.font='800 40px sans-serif';context.fillText(copy.badge,84,115);context.font='900 78px sans-serif';const lines=copy.title.replace('<br>','|').split('|');lines.forEach((line,index)=>context.fillText(line,84,225+index*88));context.font='700 34px sans-serif';context.fillText(copy.subtitle,84,420);context.font='800 36px sans-serif';context.fillText(copy.price,84,475);context.font='800 28px sans-serif';context.fillText('DRINKFLOW TEA',84,1265);const link=document.createElement('a');link.download='DrinkFlow-桂花烏龍-秋季海報.png';link.href=canvas.toDataURL('image/png');link.click();window.toast?.('海報 PNG 已下載')});
